import{_ as e,c as l,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷澤歸妹","description":"周易折中 - 雷澤歸妹","frontmatter":{"title":"雷澤歸妹","description":"周易折中 - 雷澤歸妹"},"headers":[],"relativePath":"classics/zhezhong/060.md","filePath":"classics/zhezhong/060.md"}'),h={name:"classics/zhezhong/060.md"};function n(d,a,p,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="雷澤歸妹" tabindex="-1">雷澤歸妹 <a class="header-anchor" href="#雷澤歸妹" aria-label="Permalink to “雷澤歸妹”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈歸妹序卦〉：“漸者進也，進必有所歸，故受之以歸妹。進則必有所至，故漸有歸義，歸妹所以繼漸也。歸妹者，女之歸也。妹，少女之稱。為卦震上兌下，以少女從長男也。男動而女說，又以說而動，皆男說女、女從男之義。卦有男女配合之義者四：鹹、恆、漸、歸妹也。鹹，男女之相感也。男下女，二氣感應止而說，男女之情相感之象。恆，常也。男上女下，巽順而動，陰陽皆相應，是男女居室夫婦唱隨之常道。漸，女歸之得其正也。男下女而各得正位，止靜而巽順，其進有漸，男女配合得其道也。歸妹，女之嫁歸也。男上女下，女從男也，而有說少之義。以說而動，動以說則不得其正矣，故位皆不當。初與上雖當陰陽之位，而陽在下陰在上，亦不當位也。與漸正相對。鹹、恆夫婦之道，漸、歸妹女歸之義。鹹與歸妹，男女之情也。鹹止而說，歸妹動於說，皆以說也。恆與漸，夫婦之義也。恆巽而動，漸止而巽，皆以巽順也。男女之道，夫婦之義，備於是矣。歸妹為卦，澤上有雷，雷震而澤動，從之象也。物之隨動莫如水，男動於上而女從之，嫁歸從男之象。震長男，兌少女，少女從長男以說而動，動而相說也。人之所說者少女，故云妹為女歸之象，又有長男說少女之義，故為歸妹也。”</p><p>歸妹：徵兇，無攸利</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>婦人謂嫁曰歸妹。少女也，兌以少女而從震之長男，而其情又為以說而動，皆非正也。故卦為歸妹，而卦之諸爻自二至五皆不得正，三五又皆以柔乘剛。故其佔，徵兇而無所利也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>以說而動，動而不當，故兇。不當位，不當也。徵兇，動則兇也。如卦之義，不獨女歸無所往而利也。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>蔡氏清曰 ：不曰“妹歸”而曰“歸妹”，“歸”者在妹也。如漸則曰“女歸”矣。</li></ul><p>蔡氏清曰 ：不曰“妹歸”而曰“歸妹”，“歸”者在妹也。如漸則曰“女歸”矣。</p><ul><li>張氏振淵曰 ：妹乃少女而從長男，又其情以說而動，是其情勝而不計乎匹偶之宜者，故為歸妹。所歸在妹，不正可知，故兇而無所利也。案歸妹文意如《春秋》歸地、歸田之例，以物歸於人，非其人來取物也。歸妹所以失者有二：一則不待取而自歸，失昏姻之禮（與鹹之男下女相反也）；一則以少女歸長男，失昏姻之時（與鹹兩少之交相反也）。故不曰“妹歸”而曰“歸妹”，以明其失禮；不曰“歸女”而曰“歸妹”，以見其失時。凡彖辭直著吉凶而無他戒者，大有、鼎直曰“元亨”，此直曰“徵兇無攸利”。蓋尊賢育才者人君之盛節也，自媒自薦者士女之醜行也。</li></ul><p>張氏振淵曰 ：妹乃少女而從長男，又其情以說而動，是其情勝而不計乎匹偶之宜者，故為歸妹。所歸在妹，不正可知，故兇而無所利也。案歸妹文意如《春秋》歸地、歸田之例，以物歸於人，非其人來取物也。歸妹所以失者有二：一則不待取而自歸，失昏姻之禮（與鹹之男下女相反也）；一則以少女歸長男，失昏姻之時（與鹹兩少之交相反也）。故不曰“妹歸”而曰“歸妹”，以明其失禮；不曰“歸女”而曰“歸妹”，以見其失時。凡彖辭直著吉凶而無他戒者，大有、鼎直曰“元亨”，此直曰“徵兇無攸利”。蓋尊賢育才者人君之盛節也，自媒自薦者士女之醜行也。</p><p>象曰：澤上有雷，歸妹。君子以永終知敝</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>雷動澤隨，歸妹之象。君子觀其合之不正，知其終之有敝也。推之事物，莫不皆然。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>雷震於上，澤隨而動，陽動於上，陰說而從，女從男之象也，故為歸妹。君子觀男女配合生息相續之象，而以永其終，知有敝也。永終謂生息嗣續，永久其傳也；知敝謂知物有敝壞而為相繼之道也。女歸則有生息，故有永終之義。又夫婦之道當常永有終，必知其有敝壞之理而戒愼之。敝壞謂離隙。歸妹說以動者也，異乎恆之巽而動，漸之止而巽也。少女之說情之感動，動則失正，非夫婦正而可常之道，久必敝壞。知其必敝，則當思永其終也。天下之反目者，皆不能永終者也。不獨夫婦之道，天下之事莫不有終有敝，莫不有可繼可久之道。觀歸妹，則當思永終之戒也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>崔氏憬曰 ：歸妹，人之始終也。始則徵兇，終則無攸利，故君子以永終知敝為戒者也。</p></li><li><p>吳氏曰 ：慎曰永終知敝，言遠慮其終而知有敝也。《氓》之詩不思其反，所以終見棄於人與。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>澤上有雷，不當以澤從雷取象，當以澤感雷取象。蓋取於陰氣先動，為歸妹之義。</p><p>歸妹，天地之大義也；天地不交而萬物不興，婦妹人之終始也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>釋卦名義也。歸者，女之終；生育者，人之始。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>一陰一陽之謂道，陰陽交合，男女配合，天地之常理也。歸妹，女歸於男也，故云“天地之大義也”。男在女上，陰從陽動，故為女歸之象。天地不交，則萬物何從而生？女之歸男，乃生生相續之道。男女交而後有生息，有生息而後其終不窮。前者有終，而後者有始，相續不窮，是人之終始也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li>項氏安世曰 ：有男女然後有夫婦，天地之大義也；有夫婦然後有父子，人之終始也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>將言歸妹之兇，而先言其本——天地之大義。猶姤言柔遇剛之失，而又推本於天地相遇之正也。由此言之，陰陽原不可以相無，而惟當慎之始以防其敝者，是易之道也。</p><p>說以動，所歸妹也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>又以卦德言之。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>鄭氏汝諧曰 ：長男居上，少女居下，以女下男也。少女說以動，而又先下於男，其所歸者妹，故以徵則兇，且無攸利。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>卦德“說以動”，則與鹹之“止而說”者異矣。卦象女先於男，是所欲歸者妹也；又以少女從長男，是所歸者乃妹也。“所歸妹”一句，兼此二意，可見其失於禮又愆於義也。夫說以動，則徇乎情；所歸妹，則不能止乎禮義。此卦之所以兇乎？本義以卦德言之，實則兼卦德、卦象在內。</p><p>徵兇，位不當也；無攸利，柔乘剛也</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>又以卦體釋卦辭。男女之交，本皆正理，唯若此卦則不得其正也。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>以二體釋歸妹之義。男女相感，說而動者，少女之事故。以說而動，所歸者妹也。所以徵則兇者，以諸爻皆不當位也。所處皆不正，何動而不兇？大率以說而動，安有不失正者？不唯位不當也，又有乘剛之過。三五皆乘剛，男女有尊卑之序，夫婦有唱隨之禮，此常理也，如恆是也。苟不由常正之道，徇情肆欲，唯說是動，則夫婦瀆亂。男牽欲而失其剛，婦狃說而忘其順，如歸妹之乘剛是也。所以兇，無所往而利也。夫陰陽之配合，男女之交媾，理之常也；然從欲而流放，不由義理，則淫邪無所不至，傷身敗德，豈人理哉？歸妹之所以兇也。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>陸氏希聲曰 ：易以鹹、恆為夫婦之道，漸、歸妹為夫婦之義。漸四爻得正，故女歸吉；歸妹四爻失正，故徵兇。</p></li><li><p>吳氏曰 ：慎曰，卦以少女從長男，則非其配偶；說以動，則恣情縦欲；中爻不正，則陰陽皆失其常；三五柔乘剛，則不順。宜其兇也。然四者又以“說以動”為重。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>中四爻皆失正位者，除未濟外，惟睽、解及此卦。而家人、睽、漸、歸妹皆言男女之道者也。家人以得位而正，故睽以失位而乖；漸以得位而吉，故歸妹以失位而兇也。他卦有柔乘剛而義與歸妹不同者，義與卦變相關。</p><p>初九：歸妹以娣，跛能履，徵吉</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>初九居下而無正應，故為娣象。然陽剛在女子為賢正之德，但為娣之賤，僅能承助其君而已，故又為跛能履之象。而其佔，則徵吉也。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>女之歸，居下而無正應，娣之象也。剛陽在婦人，為賢貞之德，而處卑順，娣之賢正者也。處說居下，為順義。娣之卑下，雖賢何所能為？不過自善其身以承助其君而已。如跛之能履，言不能及遠也。然在其分為善，故以是而行則吉也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>孔氏穎達曰 ：徵吉者，少長非偶為妻而行則兇，為娣而行則吉。</li></ul><p>孔氏穎達曰 ：徵吉者，少長非偶為妻而行則兇，為娣而行則吉。</p><ul><li>胡氏瑗曰 ：跛者，足之偏也。侄娣非正配而能盡其道以配君子，猶足之雖偏而能履地而行，不至於廢也。</li></ul><p>胡氏瑗曰 ：跛者，足之偏也。侄娣非正配而能盡其道以配君子，猶足之雖偏而能履地而行，不至於廢也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>初在下，娣之象。凡女之歸，不待六禮備者為失禮，惟娣可以從歸而不嫌於失禮；少長非偶者為失時，惟娣可以待年而不嫌於失時。是卦義雖兇，而於初則無嫌，故變“徵兇”而為“徵吉”也。</p><p>象曰：歸妹以娣，以恆也。跛能履，吉，相承也</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>恆謂有常久之德。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>歸妹之義，以說而動，非夫婦能常之道。九乃剛陽有賢貞之德，雖娣之微，乃能以常者也。雖在下不能有所為，如跛者之能履，然徵而吉者，以其能相承助也。能助其君，娣之吉也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>鄭氏汝諧曰 ：初少女且微而在下，以娣媵而歸，乃其常也。娣媵不能成內助之功，雖有其德，如跛者之履耳。跛者之履，雖不足以有行，然亦可以行者，以其佐小君能相承助也。如是而徵，則為安分，故吉。</p></li><li><p>俞氏琰曰 ：相承者，佐其嫡以相與奉承其夫也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>言以恆者，女而自歸非常，惟娣則從嫡而歸，乃其常也。</p><p>九二：眇能視，利幽人之貞</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>眇能視，承上爻而言。九二陽剛得中，女之賢也。上有正應而反陰柔不正，乃女賢而配不良，不能大成內助之功，故為眇能視之象。而其佔，則利幽人之貞也。幽人，亦抱道守正而不偶者也。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>九二陽剛而得中，女之賢正者也。上有正應而反陰柔之質，動於說者也。乃女賢而配不良，故二雖賢不能自遂以成其內助之功，適可以善其身而小施之，如眇者之能視而已，言不能及遠也。男女之際，當以正禮。五雖不正，二自守其幽靜貞正，乃所利也。二有剛正之德，幽靜之人也。二之才如是，而言利貞者，利言宜於如是之貞，非不足而為之戒也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>郭氏雍曰 ：九二剛中，賢女也。守其幽獨之操，不奪其志，故曰“利幽人之貞”。</li></ul><p>郭氏雍曰 ：九二剛中，賢女也。守其幽獨之操，不奪其志，故曰“利幽人之貞”。</p><ul><li>胡氏一桂曰 ：初二“跛”、“眇”，兌毀折象。履卦六三亦兌體，故取象同。</li></ul><p>胡氏一桂曰 ：初二“跛”、“眇”，兌毀折象。履卦六三亦兌體，故取象同。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>此卦與漸相似。凡以陰應陽者，女之有配者也；以陰應陰、以陽應陽者，女之無配者也。若以陽應陰，則雖有應而反莫類比之，無應者加甚矣，乃女之有配而失配者也。衛詩曰：“汎彼柏舟，亦汎其流”，則配之不良者也；又曰：“汎彼柏舟，在彼中河”，則配之不終者也。然皆自執其志，如石之不移，至於之死而矢靡他，豈非所謂“幽人之貞”乎？凡足以兩而行，目以兩而明，夫婦以兩而成。跛者一正而一偏也，眇者一昏而一明也。娣雖屈於偏側而猶能佐理，故曰“能履”；幽人雖失所仰望，而其志炯然，故曰“能視”。</p><p>象曰：利幽人之貞，未變常也</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>守其幽貞，未失夫婦常正之道也。世人以媟狎為常，故以貞靜為變常，不知乃常久之道也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>俞氏琰曰 ：屯六二曰“反常”，謂字乃女子之常，不字則非常。至十年之後而乃字，則返其常也。此曰“未變常”，謂嫁者女子之常，九二不願嫁，似乎變常，然能以幽靜自守，是亦女德之常，未為變常也。</p></li><li><p>來氏知德曰 ：一與之齊，終身不改，此婦道之常也。守幽人之貞，則未變其常矣。</p></li></ul><p>六三：歸妹以須，反歸以娣</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>六三陰柔而不中正，又為說之主，女之不正，人莫之取者也。故為未得所適而反歸為娣之象，或曰“須”，女之賤者。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>三居下之上，本非賤者，以失德而無正應，故為欲有歸而未得其歸，須待也。待者，未有所適也。六居三不當位，德不正也，柔而尚剛，行不順也。為說之主，以說求歸，動非禮也。上無應，無受之者也，無所適，故須也。女子之處如是，人誰取之？不可以為人配矣。當反歸而求為娣媵則可也，以不正而失其所也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>陸氏希聲曰 ：在天文，織女為貴，須女為賤。</li></ul><p>陸氏希聲曰 ：在天文，織女為貴，須女為賤。</p><ul><li>胡氏炳文曰 ：初九居下，娣也。六三居下之上，非娣也。陰柔而不中正，又為兌說之主，無德之女也。無德之女，人無取之者，故本宜須而反歸以娣也。</li></ul><p>胡氏炳文曰 ：初九居下，娣也。六三居下之上，非娣也。陰柔而不中正，又為兌說之主，無德之女也。無德之女，人無取之者，故本宜須而反歸以娣也。</p><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>須當從本義賤女之解。是為三不中正而無應，故取象於女之賤者，人不之取，但反歸而為娣也。然亦惟下卦無應，有娣之象；從在上之同類而歸也。上卦無應，則並無娣之象矣。故在四為愆期，在上為虛筐。</p><p>象曰：歸妹以須，未當也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>未當者，其處其德其求歸之道皆不當，故無取之者，所以須也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>朱氏震曰 ：六三居不當位，德不正也。柔而上剛，行不順也。為說之主，以說而歸，動非禮也。上無應，無受之者也。如是而賤矣，故曰“未當也”。未當故無取之者，反歸以娣也。</li></ul><p>九四：歸妹，愆期，遲歸有時。</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>九四以陽居上體而無正應，賢女不輕從人而愆期，以待所歸之象，正與六三相反。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>九以陽居四，四上體地之高也。陽剛在女子為正徳，賢明者也。無正應，未得其歸也。過時未歸，故云愆期。女子居貴高之地，有賢明之資，人情所願取，故其愆期乃為有時，蓋自有待，非不售也。待得佳配而後行也。九居四雖不當位而處柔，乃婦人之道。以無應，故為愆期之義。而聖人推理以女賢而愆期，蓋有待也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏瑗曰：以剛陽之質居陰柔之位，不為躁進，故待其禮之全備，俟其年之長大，然後歸於君子，斯得其時也。遲待也。</li></ul><p>象曰：愆期之志，有待而行也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>所以愆期者，由已而不由彼。賢女人所願取，所以愆期，乃其志欲有所待，待得佳配而後行也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰 ：嫁宜及時，今乃過期而遲歸者，此嫁者之志欲有所待而後乃行也。</p></li><li><p>俞氏琰曰 ：爻辭言愆期，而爻傳直述其志，以見愆期在我而不苟從人，蓋有待而行，非為人所棄也。行謂出嫁，《詩·泉水》雲：“女子有行”是也。</p></li></ul><p>六五：帝乙歸妹，其君之袂不如其娣之袂，良月幾望，吉。</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>六五柔中居尊，下應九二，尚徳而不貴飾，故為帝女下嫁而服不盛之象。然女徳之盛無以加此，故又為月幾望之象，而佔者如之則吉也。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>六五居尊位，妹之貴高者也。下應於二，為下嫁之象。王姬下嫁，自古而然。至帝乙而後正昏姻之禮，明男女之分。雖至貴之女，不得失柔巽之道，有貴驕之志。故《易》中陰尊而謙降者，則曰帝乙歸妹（《泰》六五是也）。貴女之歸，唯謙降以從禮，乃尊高之徳也。不事容飾以說於人，娣媵者以容飾為事者也。衣袂所以為容飾也。六五尊貴之女，尚禮而不尚飾，故其袂不及其娣之袂良也。良，羙好也。月望，陰之盈也，盈則敵陽矣。幾望，未至於盈也。五之貴高，常不至於盈極，則不亢其夫，乃為吉也。女之處尊貴之道也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>薛氏溫其曰：至尊之妹必歸於夫人倫之正。案，女不待夫家之求而自歸，非正也，卦之所以兇也。然惟天子之女，則必求於夫家而自歸焉，是歸妹之義。在他人則為越禮犯義而兇，在天子則為降尊屈貴而吉矣。六五居尊而下應九二，適合此象，故其辭如此。卦惟此爻有應，而又于歸妹之義正為所宜，而非所病，則其為吉宜矣。</li></ul><p>站長：晚清尚秉和著有《周易尚氏學》，其中論點認為，西漢時期的易學家孟喜、荀爽皆做「月既望」，詳情可看本站的《周易尚氏學》。</p><p>象曰：帝乙歸妹，不如其娣之袂良也；其位在中，以貴行也</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>以其有中德之貴而行，故不尚飭。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>以帝乙歸妹之道言，其袂不如其娣之袂良，尚禮而不尚飾也。五以柔中在尊高之位，以尊貴而行中道也。柔順降屈，尚禮而不尚飾，乃中道也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏申子曰 ：上二句舉爻辭，下二句釋之也。言五居尊位而用中，故能以至貴而行其勤儉謙遜之道也。</li></ul><p>上六：女承筐無實，士刲羊無血，無攸利。</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>上六以陰柔居歸妹之終而無應，約婚而不終者也，故其象如此，而於佔為無所利也。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>上六女歸之終而無應，女歸之無終者也。婦者所以承先祖奉祭祀，不能奉祭祀，則不可以為婦矣。筐篚之實，婦職所供也。古者房中之爼、葅歜之類，後夫人職之。諸侯之祭，親割牲，卿士大夫皆然。割取血以祭，禮雲血祭盛氣也。女當承事筐篚而無實，無實則無以祭，謂不能奉祭祀也。夫婦共承宗廟，婦不能奉祭祀，乃夫不能承祭祀也。故刲羊而無血，亦無以祭也，謂不可以承祭祀也。婦不能奉祭祀，則當離絕矣，是夫婦之無終者也。何所往而利哉？</p><h3 id="集說-15" tabindex="-1">集說 <a class="header-anchor" href="#集說-15" aria-label="Permalink to “集說”">​</a></h3><ul><li>胡氏炳文曰：震有虛筐之象，兌羊象。上與三皆陰虛而無應，故有承筐無實、刲羊無血之象。程傳以為女歸之無終，本義以為約婚而不終。蓋曰士曰女，未成夫婦也。先女而後士，罪在女也，故無攸利之佔與卦辭同。</li></ul><p>象曰：上六無實，承虛筐也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>筐無實是空筐也，空筐可以祭乎？言不可以奉祭祀也。女不可以承祭祀，則離絕而已，是女歸之無終者也。</p><h3 id="集說-16" tabindex="-1">集說 <a class="header-anchor" href="#集說-16" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏宗傳曰 ：專取虛筐無實為言者，上六女子也。</li></ul>',141)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
